/// The SDK asks the learner whether to share recitations (section Sharing). This library has no UI: the app shows
/// its own sheet with these strings and reports the tap with tf_sharing_answer.
enum TfAskKind {
  TF_ASK_SHEET(1),
  TF_ASK_CARD(2);

  final int value;
  const TfAskKind(this.value);

  static TfAskKind fromValue(int value) => switch (value) {
    1 => TF_ASK_SHEET,
    2 => TF_ASK_CARD,
    _ => throw ArgumentError('Unknown value for TfAskKind: $value'),
  };
}

/// What ran or will run the model. Here always {"cpu", "cpu", "cpu", NULL}: the exact CPU engine, no accelerator.
/// The strings are static.
final class TfBackend extends ffi.Struct {
  /// "cpu" or "accelerator"
  external ffi.Pointer<ffi.Char> kind;

  /// "cpu"
  external ffi.Pointer<ffi.Char> name;

  /// "cpu": no accelerator here
  external ffi.Pointer<ffi.Char> stage;

  /// NULL
  external ffi.Pointer<ffi.Char> reason;

  static ffi.Pointer<TfBackend> $allocate(
    ffi.Allocator $allocator, {
