final class TfClientOptions extends ffi.Struct {
  /// the desktop key from sdk.quranlab.ai (qlk_v1_...); required
  external ffi.Pointer<ffi.Char> key;

  /// the app's id as registered for the key (Windows: package family name or
  /// AppUserModelID; Linux: a reverse-DNS id); required
  external ffi.Pointer<ffi.Char> app_id;

  /// NULL: "0" (registration's placeholder). 4.0.1: cleaned to 0-9 A-Z a-z . + -
  /// (the leading . + - dropped, at most 32 characters) for registration ("0" when
  /// nothing is left) and every config request (left out there when not known)
  external ffi.Pointer<ffi.Char> app_version;

  /// a folder the app can write: the SDK's state and the model files; NULL:
  /// %LOCALAPPDATA%/<app_id>/tajweedformer, or $XDG_DATA_HOME (~/.local/share) on Linux
  external ffi.Pointer<ffi.Char> storage;

  /// the copy deck's language, BCP 47; NULL: "en"
  external ffi.Pointer<ffi.Char> language;

  /// the SDK asks to show the sharing sheet
  external ffi.Pointer<
    ffi.NativeFunction<
      ffi.Void Function(
        ffi.Pointer<ffi.Void> user,
        ffi.Pointer<TfConsentRequest> request,
      )
    >
  >
  on_consent;

  /// 1 in the app's debug builds: the client logs for the developer (a newer SDK,
  /// a pin the server could not honour); 0: it logs nothing
  @ffi.Int()
  external int debug;

  /// where that log goes; NULL: stderr. level 0 debug,
  /// 1 info, 2 warning, 3 error
  external ffi.Pointer<
    ffi.NativeFunction<
      ffi.Void Function(
        ffi.Pointer<ffi.Void> user,
        ffi.Int level,
        ffi.Pointer<ffi.Char> message,
      )
    >
  >
  on_log;

  /// passed to on_consent and on_log
  external ffi.Pointer<ffi.Void> user;

  static ffi.Pointer<TfClientOptions> $allocate(
    ffi.Allocator $allocator, {
    required ffi.Pointer<ffi.Char> key,
    required ffi.Pointer<ffi.Char> app_id,
    required ffi.Pointer<ffi.Char> app_version,
    required ffi.Pointer<ffi.Char> storage,
    required ffi.Pointer<ffi.Char> language,
    required ffi.Pointer<
      ffi.NativeFunction<
        ffi.Void Function(
          ffi.Pointer<ffi.Void> user,
          ffi.Pointer<TfConsentRequest> request,
        )
      >
    >
    on_consent,
    required int debug,
    required ffi.Pointer<
      ffi.NativeFunction<
        ffi.Void Function(
          ffi.Pointer<ffi.Void> user,
          ffi.Int level,
          ffi.Pointer<ffi.Char> message,
        )
      >
    >
    on_log,
    required ffi.Pointer<ffi.Void> user,
  }) => $allocator<TfClientOptions>()
    ..ref.key = key
    ..ref.app_id = app_id
    ..ref.app_version = app_version
    ..ref.storage = storage
    ..ref.language = language
    ..ref.on_consent = on_consent
    ..ref.debug = debug
    ..ref.on_log = on_log
    ..ref.user = user;
}

/// 4.0.1: options added after 4.0.0, given to tf_client_create2. It starts with its own size, so an app built against
/// any 4.0 header runs with any later 4.0 library: a field is read only when it lies wholly within `size`, and fields
/// are only ever appended, each optional (NULL or 0: not set). Set `size` from the header the app is built with:
/// TfClientOptionsExt ext = {.size = sizeof ext, .app_build = "412"};
/// The library copies what it needs during the call and keeps no pointer into it.
final class TfClientOptionsExt extends ffi.Struct {
  /// sizeof(TfClientOptionsExt) of the header the app was built with; below 4:
  /// TF_ERR_INVALID_ARGUMENT
  @ffi.Uint32()
  external int size;

  /// the app's build number ("412"); NULL: not known. With app_version it goes on every
  /// request for Quran Lab's signed config, so the model version rules set for the app
  /// on sdk.quranlab.ai can give older releases of the app the model they were built
  /// for. Cleaned as app_version is and left out when nothing is left; nothing else
  /// carries it
  external ffi.Pointer<ffi.Char> app_build;

  static ffi.Pointer<TfClientOptionsExt> $allocate(
    ffi.Allocator $allocator, {
    required int size,
    required ffi.Pointer<ffi.Char> app_build,
  }) => $allocator<TfClientOptionsExt>()
    ..ref.size = size
    ..ref.app_build = app_build;
}

