/// The decoded layer: what the model heard, ready to show. Plain data; it belongs to the chunk or the Heads it
/// came with.
final class TfDecoded extends ffi.Struct {
  /// the token names, separated by spaces
  external ffi.Pointer<ffi.Char> text;

  @ffi.Int()
  external int n_tokens;

  external ffi.Pointer<TfToken> tokens;

  @ffi.Int()
