  /// [n_frames, top_k]: each frame's best tokens, best first (NULL when top_k 0)
  external ffi.Pointer<ffi.Int> ranked_ids;

  /// [n_frames, top_k]
  external ffi.Pointer<ffi.Float> ranked_log_probs;

  /// [n_frames, top_k]: to the next rank; 0 for the last rank of all 38
