    required ffi.Pointer<ffi.Float> ranked_log_probs,
    required ffi.Pointer<ffi.Double> ranked_margins,
    required int settled,
    required int is_final,
  }) => $allocator<TfDecoded>()
    ..ref.text = text
    ..ref.n_tokens = n_tokens
    ..ref.tokens = tokens
    ..ref.n_words = n_words
    ..ref.words = words
