/// One structured report, safe to paste into an issue: no audio, text or identifiers.
final class TfDiagnosis extends ffi.Struct {
  /// "4.0.3"
  external ffi.Pointer<ffi.Char> sdk_version;

  /// the SDK release the signed config in force names, or NULL when it names none
  external ffi.Pointer<ffi.Char> sdk_latest;

  /// 1 accepted, 0 refused, -1 not known yet (no answer from the server)
  @ffi.Int()
  external int key_accepted;

  /// why not: the server's code, or NULL
  external ffi.Pointer<ffi.Char> key_reason;

  /// "fresh" (a current verified config), "stale" (an older one, still in use) or "none"
  external ffi.Pointer<ffi.Char> config;

  /// NULL without a model on disk
  external ffi.Pointer<ffi.Char> model_version;

  external ffi.Pointer<ffi.Char> model_build;

  @ffi.Int()
  external int model_verified;

  /// the context in force, or NULL
  external ffi.Pointer<ffi.Char> context;

  /// kind NULL without a model on disk
  external TfBackend backend;

  /// "none": this SDK has no microphone
  external ffi.Pointer<ffi.Char> microphone;

  /// bytes
  @ffi.LongLong()
  external int storage_models;

  @ffi.LongLong()
  external int storage_sharing;

  /// the code of the last error this process raised, or NULL
  external ffi.Pointer<ffi.Char> last_error;

  /// chunks dropped because the app did not read them: always 0 here (chunks come
  /// by callback, none waits)
  @ffi.Int()
  external int dropped_chunks;

  /// "unmetered", "metered", "none" or "unknown": always "unknown" here. A report
  /// only: no request of the SDK waits for a kind of network
  external ffi.Pointer<ffi.Char> connection;

  /// all of it as JSON; it also has "downloadProtocol", for which this struct
  /// has no field: the protocol the last request for a model file ran on ("h3",
  /// "h2" or "http/1.1"), null while this Client has made none in this process;
  /// and (4.0) "protected", an object: keyStore
  /// ("tpm", "software" or "file"), lease (the state of this install's model key:
  /// "valid", "grace", "expired", "stopped" or "none"), leaseExpires, refreshAfter and
  /// graceUntil (unix seconds or null), leaseClass ("attested" or "standard", or null)
  /// and core (the Core's release and target)
  external ffi.Pointer<ffi.Char> json;
}

/// The 26 errors of the catalogue shared by the four SDKs (docs: https://sdk.quranlab.ai/docs/errors).
enum TfError {
  TF_OK(0),

  /// a value the API does not accept
  TF_ERR_INVALID_ARGUMENT(-1),

  /// the server does not know the key, or it is revoked
  TF_ERR_INVALID_KEY(-2),

  /// this key needs a newer SDK
  TF_ERR_SDK_TOO_OLD(-3),

  /// the server refused this app
  TF_ERR_SERVER_REJECTED(-4),

  /// a second Client while the first is not destroyed
  TF_ERR_CLIENT_EXISTS(-5),

  /// Quran Lab has no model build for this SDK version yet
  TF_ERR_MODEL_UNAVAILABLE(-6),

  /// the model is not downloaded yet: a connection is needed once
  TF_ERR_NEEDS_CONNECTION(-7),

  /// never raised by this SDK (Windows and Linux have no such permission)
  TF_ERR_NETWORK_NOT_PERMITTED(-8),

  /// a download stopped; it resumes at the next call
  TF_ERR_DOWNLOAD_FAILED(-9),

  /// not enough space for the model
  TF_ERR_STORAGE_FULL(-10),

  /// the SDK's folder cannot be read or written
  TF_ERR_STORAGE_FAILED(-11),

  /// the folder has no model, or a listed file is gone
  TF_ERR_MODEL_MISSING(-12),

  /// the manifest or a model file is malformed
  TF_ERR_MODEL_INVALID(-13),

  /// the manifest's signature does not verify
  TF_ERR_SIGNATURE_INVALID(-14),

  /// a file's size or SHA-256 differs from the manifest
  TF_ERR_CHECKSUM_MISMATCH(-15),

  /// the build needs a newer SDK, or is not one this SDK runs
  TF_ERR_MODEL_INCOMPATIBLE(-16),

  /// this build cannot run here: the SDK supports Windows and Linux on x86-64
  TF_ERR_RUNTIME_UNSUPPORTED(-17),

  /// tf_reference_units before tf_reference_fetch
  TF_ERR_REFERENCE_MISSING(-18),

  /// the Model already has an open Session
  TF_ERR_SESSION_OPEN(-19),

  /// a call on a Session that has ended
  TF_ERR_SESSION_CLOSED(-20),

  /// the take was cancelled
  TF_ERR_CANCELLED(-21),

  /// the engine reported an error
  TF_ERR_ENGINE_FAILED(-22),

  /// never raised by this SDK (it has no microphone)
  TF_ERR_MICROPHONE_DENIED(-23),

  /// never raised by this SDK
  TF_ERR_MICROPHONE_UNAVAILABLE(-24),

  /// never raised by this SDK
  TF_ERR_INTERRUPTED(-25),

  /// a sharing call while Quran Lab's incident switch has sharing off
  TF_ERR_SHARING_UNAVAILABLE(-26);

  final int value;
  const TfError(this.value);

  static TfError fromValue(int value) => switch (value) {
    0 => TF_OK,
    -1 => TF_ERR_INVALID_ARGUMENT,
    -2 => TF_ERR_INVALID_KEY,
    -3 => TF_ERR_SDK_TOO_OLD,
    -4 => TF_ERR_SERVER_REJECTED,
    -5 => TF_ERR_CLIENT_EXISTS,
    -6 => TF_ERR_MODEL_UNAVAILABLE,
    -7 => TF_ERR_NEEDS_CONNECTION,
    -8 => TF_ERR_NETWORK_NOT_PERMITTED,
    -9 => TF_ERR_DOWNLOAD_FAILED,
    -10 => TF_ERR_STORAGE_FULL,
    -11 => TF_ERR_STORAGE_FAILED,
    -12 => TF_ERR_MODEL_MISSING,
    -13 => TF_ERR_MODEL_INVALID,
    -14 => TF_ERR_SIGNATURE_INVALID,
    -15 => TF_ERR_CHECKSUM_MISMATCH,
    -16 => TF_ERR_MODEL_INCOMPATIBLE,
    -17 => TF_ERR_RUNTIME_UNSUPPORTED,
    -18 => TF_ERR_REFERENCE_MISSING,
    -19 => TF_ERR_SESSION_OPEN,
    -20 => TF_ERR_SESSION_CLOSED,
    -21 => TF_ERR_CANCELLED,
    -22 => TF_ERR_ENGINE_FAILED,
    -23 => TF_ERR_MICROPHONE_DENIED,
    -24 => TF_ERR_MICROPHONE_UNAVAILABLE,
    -25 => TF_ERR_INTERRUPTED,
    -26 => TF_ERR_SHARING_UNAVAILABLE,
    _ => throw ArgumentError('Unknown value for TfError: $value'),
  };
}

/// What caused this thread's last failure: the same tokens as the error report Quran Lab receives for it, so an app
/// can log them, show the right words and send them in a support request. Every field is a short token, never a
/// message, path, URL, host name or identifier; a field that is absent is NULL (http_status 0).
final class TfErrorCause extends ffi.Struct {
  /// where: "config", "attest", "lease", "manifest", "download", "verify", "storage",
  /// "runtime", "model_open", "session", "sharing", ...
  external ffi.Pointer<ffi.Char> stage;

  /// why: "network" (no answer at all), "timeout", "http", "rate_limited", "refused",
  /// "hash", "quota", "memory", "engine", ... ("other" when none fits)
  external ffi.Pointer<ffi.Char> reason;

  /// the error's name: a WinHTTP or libcurl error ("ERROR_WINHTTP_TIMEOUT",
  /// "CURLE_COULDNT_CONNECT"), a Core status ("QLC_E_NOMEM"), or NULL
  external ffi.Pointer<ffi.Char> error_name;

  /// its code, or the server's error ("model_limit", "app_blocked"), or NULL
  external ffi.Pointer<ffi.Char> error_code;

  /// TF_ERR_NEEDS_CONNECTION only: "model" (the model files are not on this machine yet:
  /// connect to download them) or "lease" (the model is here and needs Quran Lab's answer
  /// to open); NULL for every other error
  external ffi.Pointer<ffi.Char> needs;

  /// the HTTP status of the answer that failed, or 0
  @ffi.Int()
  external int http_status;

  static ffi.Pointer<TfErrorCause> $allocate(
    ffi.Allocator $allocator, {
    required ffi.Pointer<ffi.Char> stage,
    required ffi.Pointer<ffi.Char> reason,
    required ffi.Pointer<ffi.Char> error_name,
    required ffi.Pointer<ffi.Char> error_code,
    required ffi.Pointer<ffi.Char> needs,
    required int http_status,
  }) => $allocator<TfErrorCause>()
    ..ref.stage = stage
    ..ref.reason = reason
    ..ref.error_name = error_name
    ..ref.error_code = error_code
    ..ref.needs = needs
    ..ref.http_status = http_status;
}

