/// Every download goes out on whatever network the machine has: nothing waits for Wi-Fi or an unmetered network.
final class TfPrefetchOptions extends ffi.Struct {
  external ffi.Pointer<
    ffi.NativeFunction<
      ffi.Void Function(
        ffi.Pointer<ffi.Void> user,
        ffi.LongLong bytes_done,
        ffi.LongLong bytes_total,
      )
    >
  >
  on_progress;

  external ffi.Pointer<ffi.Void> user;

  /// as TfModelOptions.version
  external ffi.Pointer<ffi.Char> version;

  static ffi.Pointer<TfPrefetchOptions> $allocate(
    ffi.Allocator $allocator, {
    required ffi.Pointer<
      ffi.NativeFunction<
        ffi.Void Function(
          ffi.Pointer<ffi.Void> user,
          ffi.LongLong bytes_done,
          ffi.LongLong bytes_total,
        )
      >
    >
    on_progress,
    required ffi.Pointer<ffi.Void> user,
    required ffi.Pointer<ffi.Char> version,
  }) => $allocator<TfPrefetchOptions>()
    ..ref.on_progress = on_progress
    ..ref.user = user
    ..ref.version = version;
}

final class TfRecitedAyah extends ffi.Struct {
  /// inside the reported range
  @ffi.Int()
  external int ayah;

  external TfRecitedOutcome outcome;
}

/// The app's own judgement of what was recited (SDK 4.0; the other SDKs' reportRecited with an outcome). The SDK
/// never judges: it only counts what the app says, as daily totals, labelled "as judged by your app".
final class TfRecitedOutcome extends ffi.Struct {
  /// 1 correct, 0 incorrect
  @ffi.Int()
  external int correct;

  /// incorrect only: 1 to 1000; 0 when not given
  @ffi.Int()
  external int mistakes;

  /// incorrect only: at most 8 rule ids (a lower-case letter, then at most 23 lower-case
  /// letters, digits or underscores; the calibration's ids where they apply); each adds
  /// 1 to that rule's checks and flags
  external ffi.Pointer<ffi.Pointer<ffi.Char>> rules;

  @ffi.Int()
  external int n_rules;

  static ffi.Pointer<TfRecitedOutcome> $allocate(
    ffi.Allocator $allocator, {
    required int correct,
    required int mistakes,
    required ffi.Pointer<ffi.Pointer<ffi.Char>> rules,
    required int n_rules,
  }) => $allocator<TfRecitedOutcome>()
    ..ref.correct = correct
    ..ref.mistakes = mistakes
    ..ref.rules = rules
    ..ref.n_rules = n_rules;
}

/// The expected units of each ayah: read-only data. SDK 4.0: the table is encrypted with the model and read by the
/// Core; tf_reference_fetch is refused with TF_ERR_SESSION_OPEN while a take runs, and the first tf_reference_units
/// needs the model's key on this install (TF_ERR_NEEDS_CONNECTION when it needs Quran Lab to continue). TfUnits stays valid until the Model is closed.
final class TfReference extends ffi.Opaque {}

/// ============================================================================ Session
final class TfSession extends ffi.Opaque {}

final class TfSessionOptions extends ffi.Struct {
  /// NULL: the config's inference.context, then the manifest's default
  external ffi.Pointer<ffi.Char> context;

  /// of pushed audio: 0 or 16000, or 8000 to 48000 (resampled by the engine)
  @ffi.Int()
  external int sample_rate;

  /// head names separated by commas, or "all"; NULL: "log_probs,inter1_log_probs,
  /// timing_log_probs,gem,attr_qalqalah,conf". A head not asked for is not computed
  /// (log_probs always is)
  external ffi.Pointer<ffi.Char> heads;

  /// NULL, "auto" or "cpu": the CPU engine either way
  external ffi.Pointer<ffi.Char> backend;

  /// 0, or 1 to 38: the decoded layer ranks that many tokens per frame
  @ffi.Int()
  external int top_k;

  /// 0: off. Else 500 to 60000: the take finishes after that much silence following
  /// speech (a held sound is speech: the timing head hears it)
  @ffi.Int()
  external int end_on_silence_ms;

  /// tf_session_listen only: TF_PACE_REAL_TIME (default) or TF_PACE_FAST
  @ffi.Int()
  external int pace;

  /// each chunk as it is ready, on the pushing thread
  external ffi.Pointer<
    ffi.NativeFunction<
      ffi.Void Function(ffi.Pointer<ffi.Void> user, ffi.Pointer<TfChunk> chunk)
    >
  >
  on_chunk;

  /// what happened to the take, on the pushing thread
  external ffi.Pointer<
    ffi.NativeFunction<
      ffi.Void Function(ffi.Pointer<ffi.Void> user, ffi.Pointer<TfEvent> event)
    >
  >
  on_event;

  external ffi.Pointer<ffi.Void> user;

  /// where the audio comes from, for a shared recording: "built_in", "wired", "usb",
  /// "bluetooth", "car", "continuity", "other"; NULL: "unknown"
  external ffi.Pointer<ffi.Char> input_route;

  static ffi.Pointer<TfSessionOptions> $allocate(
    ffi.Allocator $allocator, {
    required ffi.Pointer<ffi.Char> context,
    required int sample_rate,
    required ffi.Pointer<ffi.Char> heads,
    required ffi.Pointer<ffi.Char> backend,
    required int top_k,
    required int end_on_silence_ms,
    required int pace,
    required ffi.Pointer<
      ffi.NativeFunction<
        ffi.Void Function(
          ffi.Pointer<ffi.Void> user,
          ffi.Pointer<TfChunk> chunk,
        )
      >
    >
    on_chunk,
    required ffi.Pointer<
      ffi.NativeFunction<
        ffi.Void Function(
          ffi.Pointer<ffi.Void> user,
          ffi.Pointer<TfEvent> event,
        )
      >
    >
    on_event,
    required ffi.Pointer<ffi.Void> user,
    required ffi.Pointer<ffi.Char> input_route,
  }) => $allocator<TfSessionOptions>()
    ..ref.context = context
    ..ref.sample_rate = sample_rate
    ..ref.heads = heads
    ..ref.backend = backend
    ..ref.top_k = top_k
    ..ref.end_on_silence_ms = end_on_silence_ms
    ..ref.pace = pace
    ..ref.on_chunk = on_chunk
    ..ref.on_event = on_event
    ..ref.user = user
    ..ref.input_route = input_route;
}

/// Recitation sharing. Every learner is asked, under the same rules in every app, and the choice is theirs: "Not
/// now", or a yes they can take back at any time (tf_sharing_set_on), and they can delete what they shared
/// (tf_sharing_delete). The sheet is shown at most three times per install; a yes is never asked again. With a yes,
/// every take of a Session whose Model came from tf_client_model is shared in full in the background (one Ogg Opus
/// recording for takes in a row, an on-disk queue that survives restarts). Nothing is recorded or sent before a yes.
/// Quran Lab's signed config (flags.contributions) is an incident switch: until the SDK holds a signed config, and
/// while the switch is off, nothing is asked or shared.
final class TfSharing extends ffi.Struct {
  /// sharing is on: Quran Lab's incident switch (flags.contributions) is not off
  @ffi.Int()
  external int is_available;

  /// the learner said yes (and sharing is available)
  @ffi.Int()
  external int is_on;

  /// sheets shown so far
  @ffi.Int()
  external int asks;

  /// an ask waits for an answer (without on_consent: show the sheet now)
  @ffi.Int()
  external int pending_ask;

  /// recordings uploaded from this install
  @ffi.Int()
  external int shared;

  /// what a new grant would record
  external ffi.Pointer<ffi.Char> consent_version;

  /// with the app's own wording: the canonical text to send to Quran Lab; else NULL
  external ffi.Pointer<ffi.Char> consent_text;

  /// its SHA-256; NULL without the app's own wording
  external ffi.Pointer<ffi.Char> consent_sha256;

  /// with pending_ask: TF_ASK_SHEET or TF_ASK_CARD; 0 without
  @ffi.Int()
  external int pending_kind;

  static ffi.Pointer<TfSharing> $allocate(
    ffi.Allocator $allocator, {
    required int is_available,
    required int is_on,
    required int asks,
    required int pending_ask,
    required int shared,
    required ffi.Pointer<ffi.Char> consent_version,
    required ffi.Pointer<ffi.Char> consent_text,
    required ffi.Pointer<ffi.Char> consent_sha256,
    required int pending_kind,
  }) => $allocator<TfSharing>()
    ..ref.is_available = is_available
    ..ref.is_on = is_on
    ..ref.asks = asks
    ..ref.pending_ask = pending_ask
    ..ref.shared = shared
    ..ref.consent_version = consent_version
    ..ref.consent_text = consent_text
    ..ref.consent_sha256 = consent_sha256
    ..ref.pending_kind = pending_kind;
}

/// One greedy token: a run of frames with the same best token, blank removed.
final class TfToken extends ffi.Struct {
  /// token id (the vocabulary)
  @ffi.Int()
  external int id;

  /// its name, NULL when decoded without a Model
  external ffi.Pointer<ffi.Char> name;

  /// where its first, peak and last frame begin
  @ffi.Int()
  external int first_ms;

  @ffi.Int()
  external int peak_ms;

  @ffi.Int()
  external int last_ms;

  /// frames of the run, inclusive
  @ffi.Int()
  external int first_frame;

  @ffi.Int()
  external int last_frame;

  /// the run's frame with the largest top-1 log-prob
  @ffi.Int()
  external int peak_frame;

  /// the run: frame_ms * first_frame, frame_ms * (last_frame + 1)
  @ffi.Int()
  external int start_ms;

  @ffi.Int()
  external int end_ms;

  /// at the peak
  @ffi.Float()
  external double log_prob;

  /// at the peak
  @ffi.Int()
  external int runner_up;

  @ffi.Float()
  external double runner_up_log_prob;

  @ffi.Double()
  external double margin;

  /// mean sigmoid(conf) over the token's frames; NAN without the conf head
  @ffi.Double()
  external double confidence;

  static ffi.Pointer<TfToken> $allocate(
    ffi.Allocator $allocator, {
    required int id,
    required ffi.Pointer<ffi.Char> name,
    required int first_ms,
    required int peak_ms,
    required int last_ms,
    required int first_frame,
    required int last_frame,
    required int peak_frame,
    required int start_ms,
    required int end_ms,
    required double log_prob,
    required int runner_up,
    required double runner_up_log_prob,
    required double margin,
    required double confidence,
  }) => $allocator<TfToken>()
    ..ref.id = id
    ..ref.name = name
    ..ref.first_ms = first_ms
    ..ref.peak_ms = peak_ms
    ..ref.last_ms = last_ms
    ..ref.first_frame = first_frame
    ..ref.last_frame = last_frame
    ..ref.peak_frame = peak_frame
    ..ref.start_ms = start_ms
    ..ref.end_ms = end_ms
    ..ref.log_prob = log_prob
    ..ref.runner_up = runner_up
    ..ref.runner_up_log_prob = runner_up_log_prob
    ..ref.margin = margin
    ..ref.confidence = confidence;
}

/// The vocabulary.
final class TfTokens extends ffi.Struct {
  /// 38
  @ffi.Int()
  external int count;

  /// 0
  @ffi.Int()
  external int blank;

  /// the id of "|", -1 when the vocabulary has none
  @ffi.Int()
  external int word_bar;

  /// [count]
  external ffi.Pointer<ffi.Pointer<ffi.Char>> names;

  static ffi.Pointer<TfTokens> $allocate(
    ffi.Allocator $allocator, {
    required int count,
    required int blank,
    required int word_bar,
    required ffi.Pointer<ffi.Pointer<ffi.Char>> names,
  }) => $allocator<TfTokens>()
    ..ref.count = count
    ..ref.blank = blank
    ..ref.word_bar = word_bar
    ..ref.names = names;
}

final class TfUnits extends ffi.Struct {
